// Made for #WCCChallenge.
// This is just something I quickly put together for fun. 
// The code hasn't been properly cleaned.

// array to store ropes
let ropes = [];
// attraction mode. 0 or 1.
let attract = 0;
// how quickly ropes lose their speed.
let friction = 0.015;
let gravity = 0.3;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(255);
	create_ropes(15);
	strokeWeight(2)
}

function draw() {
	black_white_background();
	for (let i = 0; i < ropes.length; i++){
		let rope = ropes[i];
		rope.update();
		rope.draw();
	}
	text_on_top();
}

// creates the background rectangles
function black_white_background(){
	push();
	noStroke();
	fill(255);
	rect(0, 0, width, height / 2);
	fill(0)
	rect(0, height / 2, width, height);
	pop();
}

// uMop-apisdn
// Draws the text o top of the rest
function text_on_top(){
	push();
	translate(width / 2, height / 2);
	rotate(PI);
	textSize(18);
	textAlign(CENTER, CENTER);
	strokeWeight(5);
	stroke(255);
	fill(0);
	text('u M o p - a p ! s d n', 0, 22);
	stroke(0);
	fill(255);
	text('n W o b - e b i s q u', 0, -22);
	pop();
}

// create a number of weights and their anchor points
function create_ropes(n){
	let pos_incr = width / (n - 1);
	for (let i = 0; i < n; i++){
		let rope = new Weight(i * pos_incr, noise(i) * -100, 0);
		ropes.push(rope);
	}
}

// "weights" that are linked to anchor points to create "hanging ropes"
class Weight{
	constructor(x, y, is_down){
		this.x = x;
		this.y = y;
		this.anchor_x = x;
		this.velocity = [0, 0];
		this.weight = 1 + noise(x+y);
	}
	update(){
		// friction and gravity
		this.velocity[0] = this.velocity[0] / (friction + 1);
		this.velocity[1] = this.velocity[1] / (friction + 1) + this.weight * gravity;
		// attraction to cursor
		if(attract){
			let dist = sqrt((this.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) ** 2 + (this.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) ** 2);
			let x_attr = -((this.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) / dist);
			let y_attr = -((this.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) / dist);
			this.velocity[0] += x_attr;
			this.velocity[1] += y_attr;
		}
		// boundaries check
		let next_x = this.x + this.velocity[0];
		let next_y = this.y + this.velocity[1];
		if(next_x < 0){
			this.x = 0;
			this.velocity[0] = this.velocity[0] * -1;
		}
		else if(next_x > width){
			this.x = width;
			this.velocity[0] = this.velocity[0] * -1;
		}
		else{
			this.x = next_x;
		}
		if(next_y > height / 2){
			this.y = height / 2;
			this.velocity[1] = this.velocity[1] * -1;
		}
		else{
			this.y = next_y;
		}
	}
	// draws a line for each hanging rope and corresponding upside-down rope 
	// I ended up using anchors only for the upside-down ropes.
	draw(){
		push();
		stroke(0);
		line(this.x, 0, this.x, this.y);
		stroke(255);
		line(this.anchor_x, height, this.x, height - this.y);
		pop();
	}
}

// toggle attraction mode
function mousePressed(){
	attract = 1;
}

function mouseReleased(){
	attract = 0;
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
